using StudentCenter.ApplicationService.Application.DTOs;using StudentCenter.ApplicationService.Application.Interfaces;using StudentCenter.ApplicationService.Domain.Entities;using StudentCenter.ApplicationService.Domain.Enums;
namespace StudentCenter.ApplicationService.Application.Services;
public sealed class ApplicationService(IApplicationRepository applications,ICompetitionRepository competitions,IStudentClient students){public async Task<ApplicationResponse>CreateAsync(CreateApplicationRequest r,CancellationToken ct){var c=await competitions.GetByIdAsync(r.CompetitionId,ct)??throw new KeyNotFoundException("Competition was not found.");if(c.Status!=CompetitionStatus.Open)throw new InvalidOperationException("Applications are allowed only for an open competition.");var s=await students.GetCurrentStudentIdAsync(ct);if(await applications.GetForStudentAsync(r.CompetitionId,s,ct)!=null)throw new InvalidOperationException("You already have an application for this competition.");var a=new StudentApplication(r.CompetitionId,s);await applications.AddAsync(a,ct);return Map(a);}public async Task<ApplicationResponse>SubmitAsync(Guid id,CancellationToken ct){var a=await applications.GetAsync(id,ct)??throw new KeyNotFoundException("Application was not found.");a.Submit();await applications.SaveAsync(ct);return Map(a);}private static ApplicationResponse Map(StudentApplication a)=>new(a.Id,a.CompetitionId,a.StudentId,a.Status.ToString().ToUpperInvariant(),a.CreatedAtUtc,a.SubmittedAtUtc);}
